data Comp00;
set comp.funda;
where indfmt = 'INDL' and datafmt = 'STD' and consol = 'C' and popsrc = 'D';

data ftr1;
set comp.funda;
where indfmt = 'INDL' and datafmt = 'STD' and consol = 'C' and popsrc = 'D';

*Merge with tax incentive data;
proc sql;
create table DM4
as select a.*, b.avgftr
from DM3 as a left join fx.avgftr as b
on a.gvkey = b.gvkey and a.fyear=b.fyear;

*Clean Exhibit 21 data;
data fx.sub1;
set country31may2015;
format datadate yymmddn8. ;
informat datadate 8.;
if not missing(ncountries);
if not missing(ciknumber);

proc sort data=z1; by Country Country_Code; run;
proc transpose data=z1 out=z2 ;
by Country Country_Code;
run;

data z3 (keep=Country Country_Code year score);
set z2;
year=input(_LABEL_,12.);
score=COL1;
if Country_code ne "";

*Import ICRG Political Stability risk point dataset here (fx.ps);

*Clean Political Stability data;
proc sort data=fx.ps; by Country_Code; run;
proc transpose data=fx.ps out=ps2 ;
by Country_Code;
run;
data ps3 (keep=Country_Code year PSIndex);
set ps2;
year=input(_LABEL_,12.);
PSIndex=COL1;

***********************************Capital Controls Data*******************;
*Import Capital Controls dataset here (fx.cc);

*Merge with EX-21 data;
proc sql;
create table cc1 as
select a.ciknumber, a.datadate, a.ISO3, a.country, a.countrycount,
a.ncountries, b.kao
from fx.sub1 as a left join fx.cc as b
on a.ISO3=b.ISO3 and year(a.datadate)=b.year

*Merge with COMPUSTAT data;
PROC SQL;
CREATE TABLE fx.hedge1 AS
SELECT a.*, b.matched_date_hedge, b.l4FX_contract, b.l4Hedge
FROM fx.Comp03 as a left join fx.hedge as b
on a.cik = b.cik and a.fyear = b.fyear;

create table bd as
select a.*, b.l4depth, c.l4breadth
from fx.Comp04 as a left join depth5 as b
on a.gvkey=b.gvkey and a.fyear=b.fyear
left join breadth2 as c
on a.gvkey=c.gvkey and a.fyear=c.fyear;
quit;

data bd1;
set bd;
l4ln_breadth=log(1+l4breadth);

*Add multi-period income shifting incentive variables;
proc sql;
create table fx.Comp02
as select a.*, b.avgfetr, b.avgftr, b.lowavgftr, b.avgros, b.avgfros
from fx.Comp01 as a left join fx.avgftr as b
on a.gvkey = b.gvkey and a.fyear=b.fyear;
quit;

*Run Main Program to obtain z7;

*Merge with FX risk data;
proc sql;
create table DM6 as
select distinct a.*, b.datadate as matched_date 'matched_date', b.score*-1 as
score
from DM5 as a, z7 as b
where a.ciknumber=b.ciknumber and -12<=intck('month',
intnx('year',b.datadate,+1), a.datadate)<=12
order by a.gvkey, a.fyear;

*Final Outbound Income Shifter Sample;
data fx.Comp03;
set fx.Comp03_all;
if avgftr<0;
if 1997<=fyear<=2017;

*Estimate stock return volatility to FX risk (narrow);
%let lags=3;
ods output parameterestimates=est_narrow;
ods listing close;
proc model data=A06;
by permno datadate;
instruments cum_vwretd cum_nFXI;
parms b0 b1 b2;
cum_ret=b0+b1*cum_vwretd+b2*cum_nFXI;
fit cum_ret / gmm kernel=(bart,%eval(&lags+1),0) vardef=n; run;

data company;
set comp.company;
keep gvkey fic sic;
run;

data fx.hedge2;
set fx.hedge1a;
l4fcd_at=l4FX_contract/l4at;
if not missing(l4Hedge);
run;

*winsorize all continuous variables here (output=fx.hedge3) then export;

*keep clustered data only for fiscal year ends (full Compustat sample);
PROC upload data=fx.Comp03_all;
run;
PROC SQL;
CREATE TABLE a06 AS
SELECT a.gvkey, a.permno, a.datadate, b.cluster, b.datadate as ret_date,
b.cum_ret, b.cum_vwretd, b.cum_ewretd, c.date as FXret_date, c.cum_nFXI,
c.cum_bFXI
FROM Comp03_all as a left join a05 as b
